import React, { useState } from 'react';
import {
  EmotionAnalysis,
  RiskAssessment,
  EmotionStyle,
  ProblemAnalysis,
  InterventionInfo,
  PsychStatModel,
  ConversationPortrait,
  EMOTION_NAMES,
  PROBLEM_CATEGORY_NAMES,
  RISK_LEVEL_NAMES,
  STATS_RELIABILITY_NAMES,
  TREND_DIRECTION_NAMES,
  TrendDirection
} from '../types';

interface ReportPanelProps {
  emotion: EmotionAnalysis;
  risk: RiskAssessment;
  problem?: ProblemAnalysis;
  intervention?: InterventionInfo;
  analysisSources?: { emotion: string; risk: string; problem: string };
  llmUsed?: boolean;
  emotionStyle: EmotionStyle;
  report: string;
  statModel?: PsychStatModel;
}

const trendColor = (trend: TrendDirection): string => {
  if (trend === 'improving') return '#4CAF50';
  if (trend === 'worsening') return '#F44336';
  if (trend === 'stable') return '#607D8B';
  return '#9E9E9E';
};

const metricBarColor = (value: number, invert = false): string => {
  const v = invert ? 100 - value : value;
  if (v >= 75) return '#F44336';
  if (v >= 55) return '#FF9800';
  if (v >= 30) return '#FFC107';
  return '#4CAF50';
};

export const ReportPanel: React.FC<ReportPanelProps> = ({
  emotion,
  risk,
  problem,
  intervention,
  analysisSources,
  llmUsed,
  emotionStyle,
  report,
  statModel
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const riskColors: Record<string, string> = {
    low: '#4CAF50',
    medium: '#FF9800',
    high: '#F44336',
    critical: '#9C27B0'
  };

  const lowConfidence = emotion.confidence < 0.45;
  const toggleLabel = isExpanded ? '\u25BC' : '\u25B6';

  const handleExport = () => {
    const blob = new Blob([report], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `心理咨询报告_${new Date().toLocaleDateString('zh-CN').replace(/\//g, '-')}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const renderMetricBar = (
    label: string,
    detail: { value: number; levelText: string; percentile?: number; baselineDelta?: number },
    invert = false
  ) => (
    <div className="stat-metric-row" key={label}>
      <div className="stat-metric-head">
        <span className="stat-metric-label">{label}</span>
        <span className="stat-metric-value">
          {detail.value}
          <small> / 100</small>
        </span>
      </div>
      <div className="stat-bar-track">
        <div
          className="stat-bar-fill"
          style={{
            width: `${detail.value}%`,
            backgroundColor: metricBarColor(detail.value, invert)
          }}
        />
      </div>
      <div className="stat-metric-meta">
        <span className="stat-level-text">{detail.levelText}</span>
        {detail.percentile !== undefined && <span>历史分位 P{detail.percentile}</span>}
        {detail.baselineDelta !== undefined && (
          <span className="stat-baseline-delta">
            较基线 {detail.baselineDelta > 0 ? '+' : ''}
            {detail.baselineDelta}
          </span>
        )}
      </div>
    </div>
  );

  return (
    <div className="report-panel">
      <div
        className="report-header"
        onClick={() => setIsExpanded(!isExpanded)}
        onKeyDown={(e) => e.key === 'Enter' && setIsExpanded(!isExpanded)}
        role="button"
        tabIndex={0}
      >
        <div className="report-title">
          <span className="report-icon">{'\uD83D\uDCCB'}</span>
          <span>心理咨询报告</span>
          {statModel && (
            <span className="report-session-badge">第 {statModel.sessionIndex} 次 · 置信 {statModel.compositeScores.modelConfidence}%</span>
          )}
        </div>
        <div className="report-toggle">{toggleLabel}</div>
      </div>

      {isExpanded && (
        <div className="report-content">
          {lowConfidence && (
            <div className="report-disclaimer">
              情绪识别置信度较低，以下分析仅供参考，如有持续困扰建议寻求专业心理评估。
            </div>
          )}

          {statModel && (
            <div className="report-section stat-model-section">
              <div className="section-title-row">
                <div className="section-title">统计建模分析</div>
                <span className={`stat-reliability stat-reliability-${statModel.statsReliability}`}>
                  {STATS_RELIABILITY_NAMES[statModel.statsReliability]}
                </span>
              </div>

              {!statModel.showAdvancedStats && statModel.totalSessions < 5 && (
                <p className="stat-sample-hint">
                  再咨询 {5 - statModel.totalSessions} 次后将展示相关分析与波动统计（当前 {statModel.totalSessions} 次）。
                </p>
              )}

              <div className="stat-composite-grid">
                <div className="stat-composite-card">
                  <span className="stat-composite-label">风险量化分</span>
                  <strong>{statModel.compositeScores.riskScore}</strong>
                </div>
                <div className="stat-composite-card">
                  <span className="stat-composite-label">情绪强度</span>
                  <strong>{statModel.compositeScores.emotionIntensity}</strong>
                </div>
                <div className="stat-composite-card">
                  <span className="stat-composite-label">问题显著度</span>
                  <strong>{statModel.compositeScores.problemSalience}</strong>
                </div>
                <div className="stat-composite-card">
                  <span className="stat-composite-label">模型置信度</span>
                  <strong>{statModel.compositeScores.modelConfidence}%</strong>
                </div>
              </div>

              {statModel.intelligentModel && (
                <div className="intelligent-model-block">
                  <div className="stat-subtitle">三层智能融合（统计 + ML + 神经网络）</div>
                  <div className="fusion-weight-bar">
                    <span>统计 {(statModel.intelligentModel.fusionWeights.statistical * 100).toFixed(0)}%</span>
                    <span>ML {(statModel.intelligentModel.fusionWeights.machineLearning * 100).toFixed(0)}%</span>
                    <span>神经网络 {(statModel.intelligentModel.fusionWeights.neuralNetwork * 100).toFixed(0)}%</span>
                  </div>
                  <div className="intelligent-cards">
                    <div className="intelligent-card">
                      <span className="label">ML 状态聚类</span>
                      <strong>{statModel.intelligentModel.mlCluster}</strong>
                      {statModel.intelligentModel.bayesianApplied && <small>已贝叶斯收缩</small>}
                    </div>
                    <div className="intelligent-card">
                      <span className="label">下轮预测</span>
                      <strong>
                        压力 {statModel.intelligentModel.predictions.nextStress} / 焦虑{' '}
                        {statModel.intelligentModel.predictions.nextAnxiety}
                      </strong>
                    </div>
                    <div
                      className={`intelligent-card ${statModel.intelligentModel.hiddenRisk.flag ? 'risk' : ''}`}
                    >
                      <span className="label">隐性风险</span>
                      <strong>
                        {statModel.intelligentModel.hiddenRisk.flag ? '需关注' : '未触发'} (
                        {statModel.intelligentModel.hiddenRisk.score})
                      </strong>
                    </div>
                  </div>
                  <p className="intelligent-attribution">{statModel.intelligentModel.primaryConcern}</p>
                  <div className="layer-scores-table">
                    <div className="layer-scores-head">
                      <span>指标</span>
                      <span>统计</span>
                      <span>ML</span>
                      <span>神经网络</span>
                      <span>融合</span>
                    </div>
                    {(['distress', 'wellbeing', 'functional'] as const).map((key) => (
                      <div className="layer-scores-row" key={key}>
                        <span>{key === 'distress' ? '困扰度' : key === 'wellbeing' ? '幸福感' : '功能适应'}</span>
                        <span>{statModel.intelligentModel!.layerScores.statistical[key]}</span>
                        <span>{statModel.intelligentModel!.layerScores.ml[key]}</span>
                        <span>{statModel.intelligentModel!.layerScores.neural[key]}</span>
                        <span className="fused">{statModel.intelligentModel!.layerScores.fused[key]}</span>
                      </div>
                    ))}
                  </div>
                  <div className="attention-tags">
                    {Object.entries(statModel.intelligentModel.featureAttention)
                      .sort((a, b) => b[1] - a[1])
                      .slice(0, 5)
                      .map(([name, weight]) => (
                        <span key={name} className="attention-tag">
                          {name} {weight}%
                        </span>
                      ))}
                  </div>
                </div>
              )}

              <div className="stat-metrics-grid">
                {renderMetricBar('压力指数', statModel.indices.stress)}
                {renderMetricBar('焦虑指数', statModel.indices.anxiety)}
                {renderMetricBar('情绪平稳度', statModel.indices.moodStability, true)}
                {renderMetricBar('心理困扰度', statModel.indices.distress)}
                {renderMetricBar('幸福感指数', statModel.indices.wellbeing, true)}
                {renderMetricBar('功能适应度', statModel.indices.functionalCapacity, true)}
              </div>

              {statModel.trends.length > 0 && (
                <div className="stat-trends-block">
                  <div className="stat-subtitle">时序趋势</div>
                  <div className={`stat-trends-table ${statModel.showAdvancedStats ? '' : 'stat-trends-compact'}`}>
                    {statModel.trends.map((t) => (
                      <div className="stat-trend-row" key={t.metricKey}>
                        <span className="stat-trend-name">{t.metric}</span>
                        <span className="stat-trend-current">{t.current}</span>
                        <span className="stat-trend-delta">
                          {t.delta !== undefined ? `${t.delta > 0 ? '+' : ''}${t.delta}` : '—'}
                        </span>
                        {statModel.showAdvancedStats && (
                          <>
                            <span className="stat-trend-ewma">EWMA {t.ewma ?? '—'}</span>
                            <span className="stat-trend-avg">均值 {t.movingAvg3 ?? '—'}</span>
                            <span className="stat-trend-vol">σ {t.volatility ?? '—'}</span>
                          </>
                        )}
                        <span className="stat-trend-dir" style={{ color: trendColor(t.trend) }}>
                          {TREND_DIRECTION_NAMES[t.trend]}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className={`stat-correlation-note ${statModel.correlations.visible ? '' : 'muted'}`}>
                {statModel.correlations.note}
              </div>

              {statModel.distributions.emotionFreq.length > 0 && (
                <div className="stat-distribution-block">
                  <div className="stat-subtitle">历史分布（累计 {statModel.totalSessions} 次）</div>
                  <div className="stat-distribution-tags">
                    {statModel.distributions.emotionFreq.slice(0, 4).map((e) => (
                      <span key={e.emotion} className="stat-dist-tag">
                        {e.emotion} {e.share}%
                      </span>
                    ))}
                    {statModel.distributions.problemFreq.slice(0, 2).map((p) => (
                      <span key={p.category} className="stat-dist-tag problem">
                        {p.category} {p.share}%
                      </span>
                    ))}
                  </div>
                </div>
              )}

              <ul className="stat-summary-list">
                {statModel.summaryLines.map((line, i) => (
                  <li key={i}>{line}</li>
                ))}
              </ul>
            </div>
          )}

          {(analysisSources || llmUsed !== undefined) && (
            <div className="report-section">
              <div className="section-title">分析来源</div>
              <p className="analysis-source-line">
                情绪：{analysisSources?.emotion || 'rule'}
                {' · '}
                风险：{analysisSources?.risk || 'rule'}
                {' · '}
                问题：{analysisSources?.problem || 'rule'}
                {llmUsed ? '（已启用 LLM 辅助）' : '（仅规则引擎）'}
              </p>
            </div>
          )}

          {intervention && (
            <div className="report-section">
              <div className="section-title">干预框架</div>
              <div className="framework-badge">{intervention.frameworkName}</div>
            </div>
          )}

          {problem && (
            <div className="report-section">
              <div className="section-title">问题分类</div>
              <div className="problem-card">
                <span className="problem-main">
                  {PROBLEM_CATEGORY_NAMES[problem.category] || problem.category}
                </span>
                <span className="confidence">置信度: {(problem.confidence * 100).toFixed(0)}%</span>
                {problem.subcategories.length > 0 && (
                  <div className="problem-subs">
                    可能涉及：{problem.subcategories.slice(0, 4).join('、')}
                  </div>
                )}
              </div>
            </div>
          )}

          <div className="report-section">
            <div className="section-title">情绪分析</div>
            <div className="emotion-card" style={{ borderColor: emotionStyle.color }}>
              <div className="emotion-header">
                <span className="emotion-badge" style={{ backgroundColor: emotionStyle.color }}>
                  {EMOTION_NAMES[emotion.emotion] || emotion.emotion}
                </span>
                <span className="confidence">置信度: {(emotion.confidence * 100).toFixed(0)}%</span>
              </div>
              {emotion.secondaryEmotions.length > 0 && (
                <div className="secondary-emotions">
                  次要情绪：{emotion.secondaryEmotions.map((e) => EMOTION_NAMES[e] || e).join('、')}
                </div>
              )}
              {emotion.keywords.length > 0 && (
                <div className="emotion-keywords">
                  <span className="keywords-label">关键词:</span>
                  {emotion.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag">
                      {kw}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">风险评估</div>
            <div className="risk-card" style={{ borderColor: riskColors[risk.level] }}>
              <div className="risk-header">
                <span className="risk-badge" style={{ backgroundColor: riskColors[risk.level] }}>
                  风险等级: {RISK_LEVEL_NAMES[risk.level]}
                </span>
              </div>
              {risk.keywords.length > 0 && (
                <div className="risk-keywords">
                  <span className="keywords-label">预警关键词:</span>
                  {risk.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag warning">
                      {kw}
                    </span>
                  ))}
                </div>
              )}
              {risk.warningMessage && (
                <div className="warning-message" style={{ borderColor: riskColors[risk.level] }}>
                  {risk.warningMessage}
                </div>
              )}
              <div className="hotline">{risk.hotline}</div>
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">完整报告</div>
            <div className="full-report">
              <pre>{report}</pre>
            </div>
          </div>

          <div className="report-actions">
            <button type="button" className="action-btn export-btn" onClick={handleExport}>
              导出报告
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
